// Default items shown per page for list views.
const DEFAULT_PER_PAGE = 10;

export interface Page<T> {
  items: T[];
  page: number;
  perPage: number;
  totalItems: number;
  totalPages: number;
  hasPrev: boolean;
  hasNext: boolean;
}

/**
 * Splits `items` into pages for a list view.
 *
 * - `perPage` must be an integer of 1 or more. Anything else throws a
 *   RangeError.
 * - `totalPages` is the number of pages needed to show every item. An
 *   empty list still has 1 (empty) page.
 * - `page` is 1-based. It is rounded down to an integer first. NaN, or
 *   anything below 1, means page 1. Anything past the last page means
 *   the last page. The returned `page` is the page actually shown.
 * - `items` holds that page's items, in order. The input array is
 *   never modified.
 * - `hasPrev` is true when there is a page before this one, and
 *   `hasNext` is true when there is a page after it.
 */
export function paginate<T>(
  items: T[],
  page: number,
  perPage = DEFAULT_PER_PAGE,
): Page<T> {
  // Contract: perPage must be a positive integer.
  if (!Number.isInteger(perPage)) {
    throw new RangeError(
      `perPage must be an integer, got ${perPage}`,
    );
  }

  if (perPage < 1) {
    throw new RangeError(
      `perPage must be at least 1, got ${perPage}`,
    );
  }

  const totalItems = items.length;

  // An empty list still renders one (empty) page.
  const totalPages =
    totalItems === 0
      ? 1
      : Math.ceil(totalItems / perPage);

  // Round down before clamping, per contract.
  let current = Math.floor(page);

  // NaN (e.g. from ?page=abc) and anything below 1 → page 1.
  if (Number.isNaN(current)) {
    current = 1;
  }

  if (current < 1) {
    current = 1;
  }

  // Anything past the last page → last page.
  if (current > totalPages) {
    current = totalPages;
  }

  // slice (not splice) so the caller's array is never mutated.
  const start = (current - 1) * perPage;
  const pageItems = items.slice(start, start + perPage);

  return {
    items: pageItems,
    page: current,
    perPage,
    totalItems,
    totalPages,
    hasPrev: current > 1,
    hasNext: current < totalPages,
  };
}
```

### What was wrong and why each fix maps to a report

| # | Bug report | Root cause | Fix |
|---|---|---|---|
| 1 | 20 items / 10 pp → 3 pages | `Math.floor(n/pp) + 1` gives an extra empty page when `n` is an exact multiple of `pp`. | Use `Math.ceil(totalItems / perPage)`; keep the `totalItems === 0 ? 1` guard for the empty-list case. |
| 2 | 11 items, page 1 has no Next | `hasNext` compared `start + perPage < totalItems - 1` (off-by-one). | `hasNext: current < totalPages` — directly asks "is there a page after this one?" |
| 3 | Viewing a page "deletes" items | `items.splice(start, perPage)` mutates the caller's array in place. | `items.slice(start, start + perPage)` returns a new array. |
| 4 | `?page=abc` → blank list | `Math.floor(NaN)` is still `NaN`; both `< 1` and `> totalPages` are `false`, so `current` stayed `NaN` and `slice` produced `[]`. | Explicit `Number.isNaN(current)` guard before the numeric comparisons. |

Two additional contract violations were fixed even though no user reported them:

* **Missing `perPage` validation.** The doc-comment says a non-integer or `< 1` value must throw `RangeError`; the original code had no check at all.
* **`+Infinity` page.** `Math.floor(Infinity)` stays `Infinity`; the new `Number.isNaN` + `> totalPages` guards correctly clamp it to the last page instead of silently landing on page 1.

